import { API_BASE_URL } from '../config/api';

export interface Product {
  id: string;
  name: string;
  price: number;
  category: string;
}

export type SortKey = 'price-asc' | 'price-desc' | 'name';

export async function fetchProducts(params: {
  query?: string;
  category?: string;
  sort?: SortKey;
}): Promise<Product[]> {
  const search = new URLSearchParams();
  if (params.query) search.set('q', params.query);
  if (params.category) search.set('category', params.category);
  if (params.sort) search.set('sort', params.sort);
  const response = await fetch(`${API_BASE_URL}/products?${search.toString()}`);
  if (!response.ok) throw new Error(`Products failed with status ${response.status}`);
  return (await response.json()) as Product[];
}

import { useCallback, useEffect, useMemo, useRef, useState } from 'react';
import { View, Text, TextInput, TouchableOpacity, FlatList, StyleSheet, SafeAreaView, ActivityIndicator } from 'react-native';
import { fetchProducts, type Product, type SortKey } from '../services/products';

const colors = {
  muted: '#8a8f8a',
  accent: '#f05039',
  bg: '#0f120e',
  surface: '#1a1f1a',
  text: '#f5f5f0',
  borderAlt: '#2a2f2a',
  textMuted: '#a8ada6',
  danger: '#ff6b5e',
}

const CATEGORIES = ['all', 'lighting', 'kitchen', 'desk'];

const sortProducts = (products: Product[], sort: SortKey): Product[] => {
    return [...products].sort((a, b) => a.name.localeCompare(b.name));
};

export function CatalogScreen(): JSX.Element {
  const [query, setQuery] = useState('');
  const [category, setCategory] = useState('all');
  const [sort, setSort] = useState<SortKey>('name');
  const [products, setProducts] = useState<Product[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const timer = useRef<ReturnType<typeof setTimeout> | null>(null);

  const load = useCallback(async (q: string, cat: string, s: SortKey) => {
    setLoading(true);
    setError(null);
    try {
      const data = await fetchProducts({ query: q || undefined, category: cat === 'all' ? undefined : cat, sort: s });
      setProducts(data);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to load products.');
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    if (timer.current) clearTimeout(timer.current);
    timer.current = setTimeout(() => { void load(query, category, sort); }, 300);
    return () => { if (timer.current) clearTimeout(timer.current); };
  }, [query, category, sort, load]);

  const sorted = useMemo(() => sortProducts(products, sort), [products, sort]);

  const renderItem = useCallback(({ item }: { item: Product }) => (
    <View style={styles.card}>
      <Text style={styles.name}>{item.name}</Text>
      <Text style={styles.category}>{item.category}</Text>
      <Text style={styles.price}>${item.price}</Text>
    </View>
  ), []);

  return (
    <SafeAreaView style={styles.safe}>
      <TextInput
        value={query}
        onChangeText={setQuery}
        placeholder="Search products…"
        placeholderTextColor="{colors.muted}"
        accessibilityLabel="Search products"
        style={styles.search}
      />
      <View style={styles.chips}>
        {CATEGORIES.map(cat => (
          <TouchableOpacity
            key={cat}
            style={[styles.chip, category === cat && styles.chipActive]}
            onPress={() => setCategory(cat)}
            accessibilityRole="button"
          >
            <Text style={[styles.chipText, category === cat && styles.chipTextActive]}>{cat}</Text>
          </TouchableOpacity>
        ))}
        <TouchableOpacity
          style={styles.sortToggle}
          onPress={() => setSort(prev => (prev === 'price-asc' ? 'price-desc' : 'price-asc'))}
          accessibilityRole="button"
        >
          <Text style={styles.sortText}>Sort: {sort === 'price-asc' ? 'low → high' : 'high → low'}</Text>
        </TouchableOpacity>
      </View>
      {loading && <ActivityIndicator color="{colors.accent}" style={styles.center} />}
      {!loading && error && <Text style={styles.error}>{error}</Text>}
      {!loading && !error && sorted.length === 0 && <Text style={styles.empty}>No products match.</Text>}
      {!loading && !error && (
        <FlatList data={sorted} renderItem={renderItem} keyExtractor={p => p.id} contentContainerStyle={styles.list} />
      )}
    </SafeAreaView>
  );
}

const styles = StyleSheet.create({
  safe: { flex: 1, backgroundColor: colors.bg },
  search: { backgroundColor: colors.surface, color: colors.text, borderRadius: 6, margin: 16, padding: 12, borderWidth: 1, borderColor: colors.borderAlt },
  chips: { flexDirection: 'row', flexWrap: 'wrap', gap: 8, paddingHorizontal: 16, marginBottom: 8 },
  chip: { backgroundColor: colors.surface, borderRadius: 16, paddingHorizontal: 12, paddingVertical: 6 },
  chipActive: { backgroundColor: colors.accent },
  chipText: { color: colors.textMuted },
  chipTextActive: { color: colors.bg },
  sortToggle: { marginLeft: 'auto' },
  sortText: { color: colors.accent },
  list: { padding: 16, gap: 12 },
  card: { backgroundColor: colors.surface, borderRadius: 8, padding: 14 },
  name: { color: colors.text, fontWeight: '600' },
  category: { color: colors.muted, fontSize: 12, marginTop: 2 },
  price: { color: colors.accent, fontWeight: '700', marginTop: 6 },
  center: { marginTop: 40 },
  error: { color: colors.danger, textAlign: 'center', marginTop: 24 },
  empty: { color: colors.muted, textAlign: 'center', marginTop: 24 },
});
